// Atomic batch approval with same-transaction audit and scoped idempotency.
package candidate

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"net/http"
	"sort"
	"strconv"
	"strings"

	"github.com/XUJiahua/enterprise_agent/internal/app"
	"github.com/XUJiahua/enterprise_agent/internal/protocol"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

const operation = "bulk-approve.v3"

// requestHash is the lowercase hex SHA-256 of
// "bulk-approve.v3\n" followed by "<byte length>:<id>" for each id in UTF-8 byte order.
func requestHash(sorted []string) string {
	h := sha256.New()
	h.Write([]byte(operation + "\n"))
	for _, id := range sorted {
		h.Write([]byte(strconv.Itoa(len(id))))
		h.Write([]byte{':'})
		h.Write([]byte(id))
	}
	return hex.EncodeToString(h.Sum(nil))
}

func New(ctx context.Context, pool *pgxpool.Pool, fallback http.Handler) (http.Handler, error) {
	approve := func(ctx context.Context, u app.Identity, key string, ids []string) (protocol.Result, bool, error) {
		if u.Role != "approver" {
			return protocol.Result{}, false, &protocol.Rejection{Status: 403}
		}
		for _, id := range ids {
			if strings.ContainsRune(id, 0) {
				return protocol.Result{}, false, &protocol.Rejection{Status: 404}
			}
		}
		// Canonical order: UTF-8 byte order (Go string comparison).
		sorted := append([]string(nil), ids...)
		sort.Strings(sorted)
		hash := requestHash(sorted)
		response, err := json.Marshal(protocol.Result{ApprovedIDs: sorted})
		if err != nil {
			return protocol.Result{}, false, err
		}

		tx, err := pool.Begin(ctx)
		if err != nil {
			return protocol.Result{}, false, err
		}
		defer tx.Rollback(ctx)
		_, err = tx.Exec(ctx, `SELECT set_config('app.tenant',$1,true),set_config('app.user',$2,true),set_config('app.role',$3,true)`, u.Tenant, u.User, u.Role)
		if err != nil {
			return protocol.Result{}, false, err
		}

		// Claim the idempotency scope first. A concurrent same-scope transaction
		// blocks on the primary key until this one commits or rolls back, so the
		// scope is serialized before any Purchase row locks are taken.
		tag, err := tx.Exec(ctx, `INSERT INTO "ActionRequest" ("tenantId","actorId",operation,key,"requestHash",response)
			VALUES ($1,$2,$3,$4,$5,$6::jsonb)
			ON CONFLICT ("tenantId","actorId",operation,key) DO NOTHING`,
			u.Tenant, u.User, operation, key, hash, string(response))
		if err != nil {
			return protocol.Result{}, false, err
		}
		if tag.RowsAffected() == 0 {
			// Scope already completed (committed): replay or conflict, no writes.
			var storedHash, storedResponse string
			err = tx.QueryRow(ctx, `SELECT "requestHash",response::text FROM "ActionRequest"
				WHERE "tenantId"=$1 AND "actorId"=$2 AND operation=$3 AND key=$4`,
				u.Tenant, u.User, operation, key).Scan(&storedHash, &storedResponse)
			if errors.Is(err, pgx.ErrNoRows) {
				// Conflicting row vanished (should not happen); ask client to retry.
				return protocol.Result{}, false, &protocol.Rejection{Status: 409}
			}
			if err != nil {
				return protocol.Result{}, false, err
			}
			if storedHash != hash {
				return protocol.Result{}, false, &protocol.Rejection{Status: 409}
			}
			var stored protocol.Result
			if err = json.Unmarshal([]byte(storedResponse), &stored); err != nil {
				return protocol.Result{}, false, err
			}
			if stored.ApprovedIDs == nil {
				stored.ApprovedIDs = []string{}
			}
			return stored, true, nil
		}

		// Lock all targets in a deterministic order; rows that are not eligible
		// (other tenant, own, already approved) are filtered out.
		rows, err := tx.Query(ctx, `SELECT id FROM "Purchase" WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted' ORDER BY id FOR UPDATE`, sorted, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}
		eligible := 0
		for rows.Next() {
			var id string
			if err = rows.Scan(&id); err != nil {
				rows.Close()
				return protocol.Result{}, false, err
			}
			eligible++
		}
		err = rows.Err()
		rows.Close()
		if err != nil {
			return protocol.Result{}, false, err
		}
		if eligible != len(sorted) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}
		tag, err = tx.Exec(ctx, `UPDATE "Purchase" SET status='approved' WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted'`, sorted, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}
		if tag.RowsAffected() != int64(len(sorted)) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}
		tag, err = tx.Exec(ctx, `INSERT INTO "ApprovalAudit" ("tenantId","purchaseId","approvedBy",operation,"idempotencyKey","fromStatus","toStatus")
			SELECT $1, t.id, $2, $3, $4, 'submitted', 'approved' FROM unnest($5::text[]) AS t(id)`,
			u.Tenant, u.User, operation, key, sorted)
		if err != nil {
			return protocol.Result{}, false, err
		}
		if tag.RowsAffected() != int64(len(sorted)) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}
		if err = tx.Commit(ctx); err != nil {
			return protocol.Result{}, false, err
		}
		return protocol.Result{ApprovedIDs: sorted}, false, nil
	}
	return protocol.HTTP(approve, fallback), nil
}

